const test = require('node:test');
const assert = require('node:assert/strict');
const { indentBody } = require('../indent.cjs');
test('preserves blank lines and final LF', () => {
  assert.equal(indentBody('Ready

Ship
', '> '), '> Ready

> Ship
');
  assert.equal(indentBody('', '--'), '');
  assert.equal(indentBody('

', 'x'), '

');
  assert.equal(indentBody('A
B', '  '), '  A
  B');
});
test('spaces count as content', () => {
  assert.equal(indentBody(' 
A
', '> '), '>  
> A
');
  assert.equal(indentBody('A
', ''), 'A
');
});

